  searchUsers(event) {
    const searchTerm = event.target.value.toLowerCase();
    if (!searchTerm) {
      this.users = [...this.originalUsers];
      return;
    }
    this.users = this.originalUsers.filter((user) => {
      const userName = user.userName.toLowerCase();
      const email = user.email.toLowerCase();
      const department = user.department.toLowerCase();
      return userName.includes(searchTerm) || email.includes(searchTerm) || department.includes(searchTerm);
    });
  }
  searchWebtools(event) {
    const searchTerm = event.target.value.toLowerCase();
    if (!searchTerm) {
      this.filteredWebtools = [...this.webtools];
      return;
    }
    this.filteredWebtools = this.webtools.filter((webtool) => {
      const webtoolName = webtool.webtool.toLowerCase();
      const users = (webtool.users || []).map((user) => user.userName.toLowerCase());
      return webtoolName.includes(searchTerm) || users.some((name) => name.includes(searchTerm));
    });
  }
  // toggleRowExpansion(index: number) {
