  // }
  toggleRowExpansion(index) {
    const tool = this.webtools[index];
    if (this.expandedWebtoolId === tool.id) {
      this.expandedWebtoolId = null;
    } else {
      this.expandedWebtoolId = tool.id;
    }
  }
